 void action(const std::string&a){try{
  if(starts(a,"item:")){selected=a.substr(5);shape=moduleType(selected)?moduleShape(selected):"straight";selection=-1;tool="paint";status("Vybráno: "+label(selected));}
  else if(starts(a,"tab:")){tab=std::stoi(a.substr(4));dropdown.clear();scroll=0;search.clear();searchEntry=false;}
  else if(a=="size-menu"||a=="orientation-menu"||a=="shape-menu"){std::string key=a=="size-menu"?"size":a=="orientation-menu"?"orientation":"shape";dropdown=dropdown==key?"":key;}
  else if(starts(a,"orientation:")){int desired=std::stoi(a.substr(12));int times=rot(desired-rotation);for(int i=0;i<times;i++)rotateSelection();dropdown.clear();}
  else if(starts(a,"shape:")){std::string desired=a.substr(6);if(moduleType(selected)||desired=="straight"||templates.contains(selected+"|"+desired)){shape=desired;selection=-1;}else status("Tento typ dílu není u zvoleného objektu dostupný.");dropdown.clear();}
  else if(starts(a,"size:")){dropdown.clear();int next=std::stoi(a.substr(5));size_t outside=0;for(auto&o:level.objects){auto b=bounds(o);if(b.x1>next||b.y1>next)outside++;}if(outside&&!confirm("Při zmenšení se odstraní "+std::to_string(outside)+" objektů mimo novou mapu. Pokračovat?"))return;level.resize(next,outside>0);selection=-1;changed();center();}
  else if(a=="paint"||a=="select"||a=="erase"||a=="pan")tool=a;
  else if(a=="grid")grid=!grid;else if(a=="wallsee")wallSee=!wallSee;else if(a=="markers")markers=!markers;else if(a=="transportsee"){transportSee=!transportSee;}
  else if(a=="center")center();else if(a=="rotate")rotateSelection();else if(a=="undo"){level.undo();selection=-1;changed();}else if(a=="redo"){level.redo();selection=-1;changed();}
  else if(a=="clear"){if(confirm("Smazat všechny objekty a startovní pozice? Terén zůstane zachován.")){level.checkpoint();level.objects.clear();selection=-1;changed();}}
  else if(a=="copy"){auto json=saveDocument().dump();if(SDL_SetClipboardText(json.c_str()))throw std::runtime_error(SDL_GetError());status("Samostatná mapa zkopírována do schránky.");}
  else if(a=="close"){if(!modified||confirm("Mapa obsahuje neuložené změny. Opravdu zavřít?"))running=false;}
  else if(a=="help"){SDL_ShowSimpleMessageBox(SDL_MESSAGEBOX_INFORMATION,"UAA - editor map","Pravé tlačítko / mezerník + tažení: posun\nR: otočit, Delete: smazat, G: mřížka\nCtrl+S/O/N: uložit / otevřít / nová\nCtrl+Z/Y: zpět / vpřed\nKolečko vlevo posouvá nabídku.\n\nVlastní kód mapeditoru: open source, licence MIT.\nHudba projektu UAA: © Karel Keslly Mazánek.\nHudba je vyjmuta z MIT; všechna práva vyhrazena.\nPodrobnosti: LICENSING.md a MUSIC-LICENSE.txt.",window);}
  else if(a=="open")chooseFile(false);else if(a=="save")chooseFile(true);
  else if(a=="new"){if(confirm("Vytvořit novou prázdnou mapu? Aktuální stav lze vrátit tlačítkem Zpět.")){level.checkpoint();level.objects.clear();level.terrain.assign(level.n,std::vector<std::string>(level.n,"grass"));selection=-1;changed();}}
  else if(a=="demo"){if(confirm("Nahradit aktuální mapu ukázkovou mapou?")){level.load(config["demo20"]);selection=-1;changed();center();}}
 }catch(const std::exception&e){status(e.what());SDL_ShowSimpleMessageBox(SDL_MESSAGEBOX_ERROR,"UAA editor",e.what(),window);}dirty=true;}
