 auto expected=app.level.objects.size();auto terrain=app.level.terrain;app.savePath(selfTestDir+"/roundtrip.uaa-map.json");app.loadPath(selfTestDir+"/roundtrip.uaa-map.json");if(app.level.objects.size()!=expected||app.level.terrain!=terrain)throw std::runtime_error("Roundtrip mapy neprošel.");
